#' @title Plot example cell profiles
#'
#' @description
#' Plots gene-level expression and chromosome arm-level
#' expression profiles for a selected cell.
#'
#' Gene expression values are displayed across the genome
#' together with chromosome arm means and reference
#' chromosome arm expression levels.
#'
#' @param xenium.obj Normalised Xenium object
#' @param cell_id Cell identifier to plot
#' @param arm_means_matrix Matrix of chromosome arm mean
#' expression values generated by compute_arm_means().
#' @param reference Reference chromosome arm profile
#' generated by compute_reference().
#'
#' @returns A ggplot2 object showing gene-level
#' expression together with chromosome arm-level and
#' reference expression profiles for a selected cell.
#'
#' @examples
#' \dontrun{
#' # Plot example cell profile
#' plot_cell_profiles(xenium.obj = xenium.obj,
#'                   cell_id = "aamfeehk-1",
#'                   arm_means_matrix = arm_means_matrix,
#'                   reference = epithelium_ref_arm_means)}
#'
#' @export
plot_cell_profiles <- function(
    xenium.obj,
    cell_id,
    arm_means_matrix,
    reference
) {

  # Check cell exists
  if (!cell_id %in% colnames(xenium.obj)) {

    stop(
      paste(
        "Cell not found:",
        cell_id
      )
    )

  }

  # Built-in annotation
  gene_info <- hg38_gene_info %>%
    dplyr::filter(
      hgnc_symbol %in% rownames(xenium.obj)
    )

  chrom_info <- hg38_chrom_info

  # Expression matrix
  log_mat <- xenium.obj@assays$Xenium$data[
    gene_info$hgnc_symbol,
    ,
    drop = FALSE
  ]

  # Expression values for selected cell
  vec <- log_mat[, cell_id]

  gene_plot <- cbind(
    gene_info,
    expr = as.vector(vec)
  )

  # Arm-level means
  arm_plot <- data.frame(
    chrom_arm = rownames(arm_means_matrix),
    mean_arm_expr = arm_means_matrix[, cell_id]
  )

  arm_plot$chrom <- sub(
    "_.*",
    "",
    arm_plot$chrom_arm
  )

  arm_plot$arm <- sub(
    ".*_",
    "",
    arm_plot$chrom_arm
  )

  arm_plot <- arm_plot[, c(
    "chrom",
    "arm",
    "mean_arm_expr"
  )]

  arm_plot <- arm_plot %>%
    dplyr::left_join(
      chrom_info %>%
        dplyr::select(
          chrom,
          p_start,
          p_end,
          q_start,
          q_end
        ),
      by = "chrom"
    )

  ggplot2::ggplot(gene_plot,
      ggplot2::aes(x = cum_mid, y = expr)) +
    ggplot2::geom_point(
      alpha = 0.5,
      size = 1
    ) +
    ggplot2::geom_vline(
      xintercept =
        chrom_info$cum_centromere_mid,
      linetype = "dashed",
      linewidth = 0.3
    ) +
    ggplot2::geom_vline(
      xintercept =
        chrom_info$cum_length,
      linewidth = 0.3
    ) +
    ggplot2::geom_segment(
      data = subset(
        arm_plot,
        arm == "p"
      ),
      ggplot2::aes(
        x = p_start,
        xend = p_end,
        y = mean_arm_expr,
        yend = mean_arm_expr,
        colour = arm
      ),
      linewidth = 0.8
    ) +
    ggplot2::geom_segment(
      data = subset(
        arm_plot,
        arm == "q"
      ),
      ggplot2::aes(
        x = q_start,
        xend = q_end,
        y = mean_arm_expr,
        yend = mean_arm_expr,
        colour = arm
      ),
      linewidth = 0.8
    ) +
    ggplot2::geom_segment(
      data = subset(
        reference,
        arm == "p"
      ),
      ggplot2::aes(
        x = p_start,
        xend = p_end,
        y = mean_arm_expr,
        yend = mean_arm_expr,
        colour = "ref"
      ),
      linewidth = 0.8,
      linetype = "11"
    ) +
    ggplot2::geom_segment(
      data = subset(
        reference,
        arm == "q"
      ),
      ggplot2::aes(
        x = q_start,
        xend = q_end,
        y = mean_arm_expr,
        yend = mean_arm_expr,
        colour = "ref"
      ),
      linewidth = 0.8,
      linetype = "11"
    ) +
    ggplot2::scale_colour_manual(
      values = c(
        p = "#E69F00",
        q = "#0072B2",
        ref = "black"
      ),
      labels = c(
        p = "Arm p",
        q = "Arm q",
        ref = "Reference"
      ),
      name = "Segment type"
    ) +
    ggplot2::scale_x_continuous(
      breaks =
        chrom_info$cum_chromosome_mid,
      labels =
        chrom_info$chrom,
      expand = c(0, 0)
    ) +
    ggplot2::theme_classic() +
    ggplot2::theme(
      axis.text.x = ggplot2::element_text(
        colour = "black",
        size = 6,
        angle = 60,
        hjust = 1
      ),
      axis.text.y = ggplot2::element_text(
        colour = "black",
        size = 6
      ),
      axis.title.y = ggplot2::element_text(
        colour = "black",
        size = 8
      ),
      legend.position = "none"
    ) +
    ggplot2::ylim(0, 8.5) +
    ggplot2::labs(
      x = "Chromosome",
      y = "Log-normalised expression"
    )
}
